KAIWA += [
(["介護職：渡辺さん、のどがかわいていませんか。","渡辺さん：うん、お茶が飲みたいな。","介護職：温かいお茶と冷たいお茶と、どちらがいいですか。","渡辺さん：温かいほうがいいよ。"],"渡辺さんは、何を飲みますか。","温かいお茶","冷たいお茶","水","ジュース","Perawat: Watanabe-san, haus? / Watanabe: Ya, mau teh. / Perawat: Teh hangat atau dingin? / Watanabe: Yang hangat.","Memilih teh hangat."),
(["介護職：内田さん、きょうは、シーツを替えますね。","内田さん：ありがとう。ベッドから降りたほうがいい？","介護職：いいえ、そのまま横を向いてください。","内田さん：わかった。"],"内田さんは、何をしますか。","横を向きます。","ベッドから降ります。","立ちます。","部屋を出ます。","Perawat: Uchida-san, hari ini saya ganti seprai. / Uchida: Terima kasih. Perlu turun dari tempat tidur? / Perawat: Tidak, tetap miring ke samping. / Uchida: Baik.","Pengguna cukup miring ke samping."),
(["介護職：竹内さん、顔色がいいですね。","竹内さん：きのうの夜、よく眠れたからね。","介護職：それはよかったです。","竹内さん：今日は、散歩に行きたいな。"],"竹内さんは、今日、何をしたいですか。","散歩に行きたいです。","寝たいです。","お風呂に入りたいです。","何もしたくないです。","Perawat: Takeuchi-san, wajah Anda segar. / Takeuchi: Kemarin malam tidur nyenyak. / Perawat: Syukurlah. / Takeuchi: Hari ini ingin jalan-jalan.","Ingin jalan-jalan."),
(["介護職：坂本さん、おむつがぬれていますね。替えましょうか。","坂本さん：お願いします。","介護職：カーテンを閉めますね。","坂本さん：ありがとう。"],"介護職は、なぜカーテンを閉めますか。","ほかの人に見られないようにするためです。","暑いからです。","明るいからです。","寝るからです。","Perawat: Sakamoto-san, popok basah. Saya ganti? / Sakamoto: Tolong. / Perawat: Saya tutup tirai. / Sakamoto: Terima kasih.","Tirai ditutup demi privasi."),
(["介護職：村上さん、このくつは、小さいですか。","村上さん：うん、ちょっときついな。","介護職：では、もう少し大きいくつを持ってきます。","村上さん：すまないね。"],"村上さんのくつは、どうですか。","小さくて、きついです。","大きすぎます。","ちょうどいいです。","新しいです。","Perawat: Murakami-san, sepatu ini kecil? / Murakami: Ya, agak sempit. / Perawat: Saya bawakan yang sedikit lebih besar. / Murakami: Maaf merepotkan.","Sepatu terlalu sempit."),
(["介護職：久保さん、あしたは、お孫さんが来ますね。","久保さん：そうなんだ。髪を切りたいな。","介護職：理容師さんに、午前中に来てもらいましょう。","久保さん：頼むよ。"],"久保さんは、あした午前中に何をしますか。","髪を切ってもらいます。","お孫さんに会います。","病院へ行きます。","お風呂に入ります。","Perawat: Kubo-san, besok cucu datang. / Kubo: Ya. Ingin potong rambut. / Perawat: Kita minta tukang cukur datang pagi. / Kubo: Tolong.","Pagi hari rambut dipotong."),
(["介護職：谷口さん、手すりを持って、ゆっくり立ってください。","谷口さん：こうかな。","介護職：はい、いいですよ。足は、ふらふらしませんか。","谷口さん：だいじょうぶ。"],"介護職は、谷口さんに何をしてもらいましたか。","手すりを持って立ってもらいました。","座ってもらいました。","歩いてもらいました。","寝てもらいました。","Perawat: Taniguchi-san, pegang pegangan dan berdirilah pelan. / Taniguchi: Begini? / Perawat: Ya, bagus. Kaki tidak goyah? / Taniguchi: Tidak apa-apa.","Berdiri berpegangan pada susuran."),
(["介護職：丸山さん、みそしるが、あついので、気をつけてください。","丸山さん：ありがとう。ふうふうして、飲むよ。","介護職：スプーンで、少しずつどうぞ。","丸山さん：わかった。"],"丸山さんは、みそしるをどうやって飲みますか。","冷ましてから、スプーンで少しずつ飲みます。","一度に全部飲みます。","冷たくして飲みます。","飲みません。","Perawat: Maruyama-san, sup miso panas, hati-hati. / Maruyama: Terima kasih. Aku tiup dulu baru minum. / Perawat: Silakan sedikit demi sedikit dengan sendok. / Maruyama: Mengerti.","Meniup lalu minum sedikit-sedikit."),
(["介護職：大野さん、昼ごはんのあと、少し横になりませんか。","大野さん：食べたばかりだから、まだいいよ。","介護職：では、30分ぐらい、いすに座っていましょう。","大野さん：そうしよう。"],"介護職は、なぜ、いすに座っていましょうと言いましたか。","食べたあとすぐに横になるのは、よくないからです。","眠いからです。","いすが好きだからです。","足が痛いからです。","Perawat: Ono-san, setelah makan siang berbaring dulu? / Ono: Baru makan, nanti saja. / Perawat: Kalau begitu duduk di kursi sekitar 30 menit. / Ono: Baik.","Setelah makan jangan langsung berbaring."),
(["介護職：武田さん、かゆいところは、ありますか。","武田さん：背中が、かゆいんだ。","介護職：見てみますね。…赤くなっています。","武田さん：ひどいかな。","介護職：看護師さんに見てもらいます。"],"介護職は、このあと何をしますか。","看護師に、背中を見てもらいます。","背中をかきます。","薬を飲ませます。","お風呂に入れます。","Perawat: Takeda-san, ada yang gatal? / Takeda: Punggung gatal. / Perawat: Saya lihat... merah. / Takeda: Parahkah? / Perawat: Saya minta perawat medis memeriksa.","Punggung merah dan gatal → diperiksa perawat medis."),
(["介護職：柴田さん、もう少し右にずれてください。","柴田さん：こうかな。","介護職：そうです。ありがとうございます。","柴田さん：これで、いいの？"],"介護職は、柴田さんにどうしてもらいましたか。","右にずれてもらいました。","左にずれてもらいました。","立ってもらいました。","座ってもらいました。","Perawat: Shibata-san, geser sedikit ke kanan. / Shibata: Begini? / Perawat: Benar. Terima kasih. / Shibata: Sudah cukup?","Diminta bergeser ke kanan."),
(["介護職：野口さん、デイサービスの車が、もうすぐ来ますよ。","野口さん：まだ、準備ができていないよ。","介護職：手伝いますね。上着とかばんは、どこですか。","野口さん：あそこのいすの上だよ。"],"上着とかばんは、どこにありますか。","いすの上にあります。","机の上にあります。","ベッドの上にあります。","車の中にあります。","Perawat: Noguchi-san, mobil day service sebentar lagi datang. / Noguchi: Belum siap. / Perawat: Saya bantu. Jaket dan tas di mana? / Noguchi: Di atas kursi di sana.","Di atas kursi."),
(["介護職：千葉さん、おなかは、すいていますか。","千葉さん：あまり。でも、くだものなら食べられそう。","介護職：では、りんごをむいてきますね。","千葉さん：楽しみ。"],"千葉さんは、何なら食べられそうですか。","くだものなら食べられそうです。","ごはんなら食べられそうです。","何も食べられません。","おやつなら食べられます。","Perawat: Chiba-san, lapar? / Chiba: Tidak terlalu. Tapi kalau buah sepertinya bisa. / Perawat: Saya kupaskan apel. / Chiba: Menantikannya.","Hanya buah yang bisa dimakan."),
(["介護職：菊池さん、おしっこが、いつもより少ないようですが。","菊池さん：きょうは、あまり水を飲んでいないからかな。","介護職：水分をとりましょう。お茶を持ってきますね。","菊池さん：うん。"],"介護職は、なぜお茶を持ってきますか。","水分をとってもらうためです。","のどがかわいたからです。","お茶が好きだからです。","薬を飲ませるためです。","Perawat: Kikuchi-san, urine hari ini lebih sedikit dari biasa. / Kikuchi: Mungkin karena kurang minum. / Perawat: Mari minum. Saya bawakan teh. / Kikuchi: Ya.","Teh untuk menambah asupan cairan."),
(["介護職：成田さん、爪が伸びていますね。切りましょうか。","成田さん：ああ、お願いします。","介護職：切ったあと、やすりをかけますね。","成田さん：ありがとう。"],"介護職は、爪を切ったあと、何をしますか。","やすりをかけます。","お風呂に入れます。","手を洗います。","薬をぬります。","Perawat: Narita-san, kuku sudah panjang. Saya potong? / Narita: Ya, tolong. / Perawat: Setelah dipotong saya haluskan dengan kikir. / Narita: Terima kasih.","Setelah dipotong, dihaluskan dengan kikir."),
(["介護職：浜田さん、これから、リハビリですよ。","浜田さん：きょうは、足が重いな。","介護職：そうですか。リハビリの先生に、伝えておきますね。","浜田さん：頼むね。"],"介護職は、リハビリの先生に何を伝えますか。","浜田さんの足が重いことを伝えます。","浜田さんが元気なことを伝えます。","リハビリをしたくないことを伝えます。","何も伝えません。","Perawat: Hamada-san, sebentar lagi rehabilitasi. / Hamada: Hari ini kakiku terasa berat. / Perawat: Begitu ya. Saya sampaikan ke terapis. / Hamada: Tolong.","Menyampaikan kondisi kaki berat ke terapis."),
]

